require_once __DIR__.'/../lib/helpers.php';send_cors_headers();$context=require_vendor(true);$vendorId=$context['vendor']['id'];$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET'){$settings=$db->prepare('SELECT * FROM vendor_shipping_settings WHERE vendor_id=:vendor');$settings->execute(['vendor'=>$vendorId]);$zones=$db->prepare('SELECT z.*, (SELECT JSON_ARRAYAGG(JSON_OBJECT("id",r.id,"calculation_type",r.calculation_type,"min_weight_grams",r.min_weight_grams,"max_weight_grams",r.max_weight_grams,"min_order_value",r.min_order_value,"max_order_value",r.max_order_value,"charge",r.charge,"additional_unit_charge",r.additional_unit_charge,"is_active",r.is_active)) FROM vendor_shipping_rates r WHERE r.zone_id=z.id) rates FROM vendor_shipping_zones z WHERE z.vendor_id=:vendor ORDER BY z.created_at');$zones->execute(['vendor'=>$vendorId]);json_response(200,['success'=>true,'settings'=>$settings->fetch()?:null,'zones'=>$zones->fetchAll()]);}if($method==='PUT'){$body=get_json_body();$coverage=trim((string)($body['coverage_model']??''));$min=(int)($body['processing_min_days']??0);$max=(int)($body['processing_max_days']??0);if(!in_array($coverage,['all_india','selected_locations'],true)||$min<0||$max<$min||$max>90)json_response(422,['success'=>false,'message'=>'Coverage and processing range are invalid.']);$db->prepare('INSERT INTO vendor_shipping_settings (vendor_id,coverage_model,processing_min_days,processing_max_days,courier_partners,base_charge,free_above,cod_enabled,fragile_handling,created_at,updated_at) VALUES (:vendor,:coverage,:min,:max,:couriers,:base,:free,:cod,:fragile,UTC_TIMESTAMP(),UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE coverage_model=VALUES(coverage_model),processing_min_days=VALUES(processing_min_days),processing_max_days=VALUES(processing_max_days),courier_partners=VALUES(courier_partners),base_charge=VALUES(base_charge),free_above=VALUES(free_above),cod_enabled=VALUES(cod_enabled),fragile_handling=VALUES(fragile_handling),updated_at=UTC_TIMESTAMP()')->execute(['vendor'=>$vendorId,'coverage'=>$coverage,'min'=>$min,'max'=>$max,'couriers'=>implode(', ',array_slice((array)($body['courier_partners']??[]),0,20)),'base'=>max(0,(float)($body['base_charge']??0)),'free'=>isset($body['free_above'])?max(0,(float)$body['free_above']):null,'cod'=>!empty($body['cod_enabled'])?1:0,'fragile'=>!empty($body['fragile_handling'])?1:0]);json_response(200,['success'=>true,'message'=>'India delivery settings saved.']);}if($method==='POST'){$body=get_json_body();$rule=trim((string)($body['rule_type']??''));if(!in_array($rule,['all_india','state','city','pincode'],true))json_response(422,['success'=>false,'message'=>'Invalid location rule.']);$state=trim((string)($body['state']??''));$city=trim((string)($body['city']??''));$from=preg_replace('/\D+/','',(string)($body['pincode_from']??''));$to=preg_replace('/\D+/','',(string)($body['pincode_to']??''));if(($rule==='state'&&$state==='')||($rule==='city'&&($state===''||$city===''))||($rule==='pincode'&&(strlen($from)!==6||strlen($to)!==6||$from>$to)))json_response(422,['success'=>false,'message'=>'State, city or PIN range is incomplete.']);$zone=uuid_string();$db->beginTransaction();try{$db->prepare('INSERT INTO vendor_shipping_zones (id,vendor_id,zone_name,rule_type,country_code,state,city,pincode_from,pincode_to,is_exclusion,is_active,created_at,updated_at) VALUES (:id,:vendor,:name,:rule,"IN",:state,:city,:from_pin,:to_pin,:excluded,1,UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute(['id'=>$zone,'vendor'=>$vendorId,'name'=>trim((string)($body['zone_name']??ucfirst($rule))),'rule'=>$rule,'state'=>$state?:null,'city'=>$city?:null,'from_pin'=>$from?:null,'to_pin'=>$to?:null,'excluded'=>!empty($body['is_exclusion'])?1:0]);foreach((array)($body['rates']??[]) as $rate){$charge=round((float)($rate['charge']??-1),2);if($charge<0)json_response(422,['success'=>false,'message'=>'Shipping charge cannot be negative.']);$db->prepare('INSERT INTO vendor_shipping_rates (id,vendor_id,zone_id,calculation_type,min_weight_grams,max_weight_grams,min_order_value,max_order_value,charge,additional_unit_charge,is_active,created_at,updated_at) VALUES (:id,:vendor,:zone,:type,:min_weight,:max_weight,:min_value,:max_value,:charge,:additional,1,UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute(['id'=>uuid_string(),'vendor'=>$vendorId,'zone'=>$zone,'type'=>in_array($rate['calculation_type']??'flat',['flat','weight','order_value'],true)?$rate['calculation_type']:'flat','min_weight'=>$rate['min_weight_grams']??null,'max_weight'=>$rate['max_weight_grams']??null,'min_value'=>$rate['min_order_value']??null,'max_value'=>$rate['max_order_value']??null,'charge'=>$charge,'additional'=>$rate['additional_unit_charge']??null]);}$db->commit();json_response(201,['success'=>true,'message'=>'Delivery zone created.','zone_id'=>$zone]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}if($method==='DELETE'){$zone=trim((string)($_GET['zone_id']??''));$db->prepare('DELETE FROM vendor_shipping_zones WHERE id=:id AND vendor_id=:vendor')->execute(['id'=>$zone,'vendor'=>$vendorId]);json_response(200,['success'=>true,'message'=>'Delivery zone removed.']);}json_response(405,['success'=>false,'message'=>'Method not allowed.']);
